**Step 1: Create MCP server factory**

```typescript
// src/server.ts
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import type { Bindings } from "./types";
import { listTables, describeTable, queryD1 } from "./tools/d1";

export function createMcpServer(env: Bindings): McpServer {
  const server = new McpServer({
    name: "mcp-cloudflare",
    version: "1.0.0",
  });

  server.tool("d1-list-tables", "List all tables in the D1 database", async () => {
    const tables = await listTables(env.DB);
    return {
      content: [{ type: "text", text: JSON.stringify(tables, null, 2) }],
    };
  });

  server.tool(
    "d1-describe",
    "Get schema information for a D1 table",
    { table: z.string().describe("Table name to describe") },
    async ({ table }) => {
      const columns = await describeTable(env.DB, table);
      return {
        content: [{ type: "text", text: JSON.stringify(columns, null, 2) }],
      };
    }
  );

  server.tool(
    "d1-query",
    "Execute a SQL query against the D1 database",
    {
      sql: z.string().describe("SQL query to execute"),
      params: z.array(z.unknown()).optional().describe("Query parameters for prepared statement"),
    },
    async ({ sql, params }) => {
      const result = await queryD1(env.DB, sql, params);
      return {
        content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
      };
    }
  );

  return server;
}
```

