import type { Context, Next } from "hono";
import { timingSafeEqual } from "hono/utils/crypto";
import type { Bindings } from "../types";

export async function bearerAuth(c: Context<{ Bindings: Bindings }>, next: Next) {
  if (c.req.path === "/health") {
    return next();
  }

  const authHeader = c.req.header("Authorization");
  if (!authHeader?.startsWith("Bearer ")) {
    return c.json({ error: "Missing or invalid Authorization header" }, 401);
  }

  const token = authHeader.slice(7);
  const expected = c.env.MCP_AUTH_TOKEN;
  if (token.length !== expected.length || !(await timingSafeEqual(token, expected))) {
    return c.json({ error: "Invalid token" }, 401);
  }

  return next();
}

